+ bool OrcaHomeBackend::has_usable_setup() const
+ {
+     const PresetBundle* presets = wxGetApp().preset_bundle;
+     const AppConfig* config     = wxGetApp().app_config;
+     if (presets == nullptr || config == nullptr || presets->filament_presets.empty())
+         return false;
