548	  } else if (onboarding.step === 'confirm_setup') content = <ConfirmSetup onboarding={onboarding} error={error} onAction={onAction} />;
549	  else if (onboarding.step === 'setup') content = <ChooseSetup error={error} onAction={onAction} />;
550	  else content = <Project error={error} onAction={onAction} onDismissError={onDismissError} />;
551	  return (
552	    <main className="onboarding">
553	      <Header onboarding={onboarding} />
554	      <div className="onboarding-stage">{content}</div>
555	      <footer className="onboarding-footer">{footerText(onboarding)}</footer>
556	    </main>
557	  );
558	}
