// The Agent's ways of connecting, drawn once for every surface that offers
// them: the JusPrin account block, one row per provider key, and one row per
// AI tool (canvas "JusPrin v2": Agent/Account Row, Agent/Provider Row,
// Agent/Your Own API Key and Agent/Tool Row, decided 2026-10-21). Agent setup
// shows one way at a time; Preferences › Agent shows all three, with the
// same rows.

import { KeyboardEvent, RefObject, useEffect, useRef, useState } from 'react';
import { AccountStatusPayload, McpToolInfo, SavedKeyInfo, SetupStatusPayload } from '../bridge/protocol';

// The page and the host ship in the same build, so this list and the host's
// setup_provider_supported() are two views of the same fact. The host still
// validates: an unsupported provider comes back as a visible setup error
// rather than a request that never answers.
export interface ProviderOption {
  id: string;
  label: string;
  // How the provider's keys start, for the placeholder and the locked field.
  prefix: string;
}

export const PROVIDERS: ProviderOption[] = [
  { id: 'anthropic', label: 'Anthropic', prefix: 'sk-ant-' },
  { id: 'openai', label: 'OpenAI', prefix: 'sk-' },
  { id: 'openrouter', label: 'OpenRouter', prefix: 'sk-or-' },
];

export function providerLabel(id: string | undefined): string {
  return PROVIDERS.find((provider) => provider.id === id)?.label ?? 'your provider';
}

export interface AccountRowProps {
  // The signed-in account, from setup_keys; absent when signed out.
  account?: SavedKeyInfo;
  status: AccountStatusPayload;
  onSignIn: () => void;
  onCancel: () => void;
  onSignOut: () => void;
}

// The JusPrin account (canvas "JusPrin v2": Agent/Account Row): signed out,
// waiting for the browser, signed in, or signed in with a sign-in that has
// ended. The browser does the signing in; this row only follows it.
export function AccountRow({ account, status, onSignIn, onCancel, onSignOut }: AccountRowProps) {
  const [copied, setCopied] = useState(false);
  const waiting = status.phase !== 'idle';
  const ended = !!account?.rejected;
  const copyLink = () => {
    if (!status.url) return;
    navigator.clipboard.writeText(status.url).then(() => setCopied(true), () => setCopied(false));
  };
  let line: React.ReactNode;
  if (waiting) {
    line = status.phase === 'checking' ? 'Checking your account…' : 'Finish signing in in your browser';
  } else if (account && ended) {
    line = (
      <span className="agent-row-status-label">
        <span className="jp-icon jp-icon-circle-alert" aria-hidden="true" />
        <span>Your sign-in for {account.account || 'this account'} has ended</span>
      </span>
    );
  } else if (account) {
    line = (
      <span className="agent-row-status-label">
        <span className="jp-icon jp-icon-check" aria-hidden="true" />
        <span>{account.account ? `Signed in as ${account.account}` : 'Signed in'}</span>
      </span>
    );
  } else {
    line = 'Free · sign in with your browser · nothing to install';
  }
  return (
    <div className="agent-account" data-testid="agent-account">
      <div className="agent-row-copy">
          <h2 className="agent-account-title">JusPrin account</h2>
          <span className={`agent-row-status${ended && !waiting ? ' agent-row-status--rejected' : account && !waiting ? ' agent-row-status--saved' : ''}`}
            data-testid="agent-account-status">{line}</span>
      </div>
      {waiting ? (
        <button type="button" className="link" onClick={onCancel}>Cancel</button>
      ) : account && !ended ? (
        <button type="button" className="agent-row-action" onClick={onSignOut}>Sign out</button>
      ) : (
        <button type="button" className="primary" onClick={onSignIn}>{ended ? 'Sign in again' : 'Continue with JusPrin'}</button>
      )}
      <div className="agent-account-detail">
      {status.phase === 'browser' && (
        <>
          <p className="agent-row-note">
            A JusPrin tab just opened. Sign in there, or create an account, and come back. This notices on its own.
          </p>
          {status.url && (
            <p className="agent-row-note">
              Didn’t open?{' '}
              <button type="button" className="link" onClick={copyLink}>{copied ? 'Link copied' : 'Copy link'}</button>
            </p>
          )}
        </>
      )}
      {!waiting && status.error && (
        <p className="agent-key-error" role="alert" data-testid="account-error">{status.error.message}</p>
      )}
      {!waiting && status.warning && <p className="agent-row-note">{status.warning}</p>}
      {!waiting && account && ended && (
        <p className="agent-row-note">Sign in again to keep using the Agent with your JusPrin account.</p>
      )}
      </div>
    </div>
  );
}

// What is stored for a provider, as its row's status line says it.
// 'sessionOnly' is a key that passed its check but could not be written to
// this computer: it works until JusPrin restarts.
export type KeyStanding = 'none' | 'saved' | 'rejected' | 'sessionOnly';

// The row's key form. 'unreachable' is a check that never got an answer, so
// the key stays locked for another try; 'refused' is one the provider
// answered no to, so the key stays open to correct.
export type KeyForm = 'closed' | 'entering' | 'checking' | 'unreachable' | 'refused';

const STANDING_LINE: Record<Exclude<KeyStanding, 'none'>, { icon: string; text: string }> = {
  saved: { icon: 'check', text: 'Key saved on this computer' },
  sessionOnly: { icon: 'triangle-alert', text: 'Working, but only until JusPrin restarts' },
  rejected: { icon: 'circle-alert', text: 'The provider rejected this key' },
};

// A key being checked stays visible so it is clear which one is in question,
// but only its known start: the rest is never echoed back.
function maskedKey(key: string, prefix: string): string {
  return `${key.startsWith(prefix) ? prefix : ''}${'•'.repeat(16)}`;
}

export interface ProviderKeyRowProps {
  provider: ProviderOption;
  standing: KeyStanding;
  // The host's start-and-last-4 hint of the stored key; never the key.
  hint?: string;
  form: KeyForm;
  error?: string;
function AgentSection({ agent, setup, savedKeys, account, mcpCatalog, actions, onConnectTool }: {
  agent: PreferencesPayload['agent']; setup: SetupStatusPayload; savedKeys: SavedKeyInfo[]; account: AccountStatusPayload;
  mcpCatalog: McpCatalogPayload | null; actions: PreferencesActions; onConnectTool: (tool: McpToolInfo) => void;
}) {
  // The tools are looked for once each time the section opens.
  useEffect(() => {
    actions.refreshTools();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  return (
    <section className="prefs-section" aria-label="Agent">
      <div className="prefs-head">
        <h2 className="prefs-title">Agent</h2>
        <p className="prefs-intro">The ways the Agent can think. Set up as many as you like; each chat picks a model from them.</p>
      </div>
      <JusPrinAccount savedKeys={savedKeys} account={account} actions={actions} />
      <ProviderKeys heading setup={setup} savedKeys={savedKeys} onCheck={actions.checkKey} onCancel={actions.cancelCheck}
        onRemove={actions.removeKey} />
      <ToolGroup heading tools={mcpCatalog?.tools ?? []} onConnect={onConnectTool} onLookAgain={actions.refreshTools} />
      <Group title="New chats start with">
        {agent.newChatChoices.length > 0 ? (
          <Row title="Model" detail="Any chat can switch from its message box.">
            <Select label="Model" value={agent.newChatProvider} onChange={(provider) => actions.set('newChatProvider', provider)}
              options={agent.newChatChoices.map((choice) => ({ value: choice.provider, label: `${choice.model} · ${choice.label}` }))} />
          </Row>
        ) : (
          <Row title="Model" detail="Add a key above, and new chats start with that provider’s model." />
        )}
      </Group>
      <div className="prefs-callout">
        <span className="jp-icon jp-icon-lock" aria-hidden="true" />
        <p>
          The provider a chat uses receives your messages, the open project’s settings and anything you attach. With a
          JusPrin account, JusPrin receives them and passes them on to the model provider it uses. JusPrin doesn’t send
          your keys anywhere else.
        </p>
      </div>
    </section>
  );
}

