// The composer's model and thinking pickers (the Composer proposal on the
// "JusPrin v2" canvas, states 5 to 8). The model menu lists every model of
// every provider with a key, under the provider's name when there is more
// than one; the thinking menu lists the levels the chosen model accepts and
// is left out when it accepts none. A choice belongs to the active chat and
// applies from its next turn. A model menu of more than SEARCH_FROM models
// (OpenRouter's runs to hundreds) starts with a search field, and a provider
// with that many shows its count beside its name.

import { ChatModelChoice, ModelCatalogPayload, ModelOptionInfo } from '../bridge/protocol';
import { ActionMenu, MenuItem, MenuSearch, MenuSection } from './ChatNavigation';

const EFFORT_LABELS: Record<string, string> = {
  none: 'Off', minimal: 'Minimal', low: 'Low', medium: 'Medium', high: 'High', xhigh: 'Extra high', max: 'Max',
  // JusPrin's own levels, which its gateway maps to the model's.
  fast: 'Fast', thorough: 'Thorough',
};

export const SEARCH_FROM = 12;

const MODEL_SEARCH: MenuSearch = { label: 'Search models', noMatch: (query) => `No models match “${query}”.` };

export function effortLabel(effort: string): string {
  return EFFORT_LABELS[effort] ?? effort;
}

// The catalog's entry for the chosen model, if its list has arrived.
export function findModel(catalog: ModelCatalogPayload, choice: ChatModelChoice): ModelOptionInfo | undefined {
  return catalog.providers.find((provider) => provider.id === choice.provider)?.models
    .find((model) => model.id === choice.model);
}

// Switching model keeps the thinking level when the new model has it, and
// otherwise leaves the level to the new model's default.
export function switchModel(choice: ChatModelChoice, provider: string, model: ModelOptionInfo): ChatModelChoice {
  return { provider, model: model.id, effort: model.efforts.includes(choice.effort) ? choice.effort : '' };
}

export function modelMenu(catalog: ModelCatalogPayload, choice: ChatModelChoice,
  onChoose: (choice: ChatModelChoice) => void): (MenuItem | MenuSection)[] {
  const grouped = catalog.providers.length > 1;
  const entries: (MenuItem | MenuSection)[] = [];
  for (const provider of catalog.providers) {
    if (grouped)
      entries.push({ section: provider.label,
        detail: provider.models.length > SEARCH_FROM ? `${provider.models.length} models` : undefined });
    const models = [...provider.models];
    // The chat's model stays choosable even before its list arrives, or when
    // the list leaves it out.
    if (provider.id === choice.provider && !models.some((model) => model.id === choice.model))
      models.unshift({ id: choice.model, label: choice.model, efforts: [] });
    for (const model of models)
      entries.push({
        key: `${provider.id}/${model.id}`,
        label: model.label,
        current: provider.id === choice.provider && model.id === choice.model,
        matches: [model.label, provider.label],
        onSelect: () => onChoose(switchModel(choice, provider.id, model)),
      });
    if (provider.state === 'loading')
      entries.push({ key: `${provider.id}/loading`, label: 'Loading models…', disabled: true,
        matches: [provider.label], onSelect: () => {} });
    if (provider.state === 'failed')
      entries.push({ key: `${provider.id}/failed`, label: 'Couldn’t load the model list', disabled: true,
        matches: [provider.label], onSelect: () => {} });
  }
  return entries;
}

export function ModelPickers({ catalog, choice, disabled, onChoose }: {
  catalog: ModelCatalogPayload;
  choice: ChatModelChoice;
  disabled: boolean;
  onChoose: (choice: ChatModelChoice) => void;
}) {
  const model = findModel(catalog, choice);
  const efforts = model?.efforts ?? [];
  // An unset level shows the model's own default where the provider names
  // it; where it does not, it reads "Default".
  const shownEffort = choice.effort || model?.defaultEffort || '';
  const models = modelMenu(catalog, choice, onChoose);
  const modelCount = models.filter((entry) => !('section' in entry) && !entry.disabled).length;
  // Only the model picker gives up width in a narrow pane; the thinking
  // picker drops its "Thinking:" instead (Composer measures which).
  return <>
    <ActionMenu label="Model" className="composer-model-menu" text={model?.label ?? choice.model} above
      disabled={disabled} items={models} search={modelCount > SEARCH_FROM ? MODEL_SEARCH : undefined} />
    {efforts.length > 0 && <ActionMenu label="Thinking" above disabled={disabled} prefixed
      text={shownEffort ? effortLabel(shownEffort) : 'Default'}
      items={efforts.map((effort) => ({
        key: effort,
        label: effortLabel(effort),
        current: effort === shownEffort,
        onSelect: () => onChoose({ ...choice, effort }),
      }))} />}
  </>;
}

void AgentHost::start_turn(const std::string& source_message_id)
{
    if (m_chat_transition_blocked)
        return;
    // As a sent message does: the title is optional, the turn is not. The
    // source ID keeps an app-initiated file report attached to its own turn.
    cancel_conversation_title();
    if (agent_busy()) {
        m_queued_user_message_ids.push_back(source_message_id);
        return;
    }
    begin_reply(source_message_id);
}

void AgentHost::set_session_tool_preflight(ToolExecutionCoordinator::ExtensionPreflight preflight)
{
    m_tools.set_extension_preflight(std::move(preflight));
}

void AgentHost::send_page_envelope(const std::string& type, const json& payload)
{
    send_envelope(type.c_str(), payload.dump());
}

AgentHost::SubmitResult AgentHost::submit_issue_message(const std::string& client_message_id, const std::string& text,
                                                        const std::string& context_json, std::string* refusal)
{
    // What refuses the page's own send refuses this one too: a button outside
    // the page is no way around the chat's state.
    std::optional<AgentError> refused = user_message_refusal();
    if (!refused && (client_message_id.empty() || text.empty()))
        refused = AgentError{"invalid_payload", "A message needs an id and text.", false};
    if (refused) {
        if (refusal != nullptr)
            *refusal = refused->code;
        return SubmitResult::Refused;
    }
    if (m_persistence.document().client_message_lookup(client_message_id))
        return SubmitResult::Duplicate;

    ConversationMessage message;
    message.text              = text;
    message.client_message_id = client_message_id;
    message.issue_context     = context_json;
    return accept_user_message(std::move(message), {}, /*from_composer=*/false) ? SubmitResult::Started : SubmitResult::Queued;
}

void AgentHost::begin_reply(const std::string& user_message_id)
{
    ProjectStateDocument& document = m_persistence.document();
    std::string conversation_id = document.conversation_of_message(user_message_id);
    if (conversation_id.empty())
        conversation_id = document.active_conversation_id();

    // Every session's instructions come from its page, and the app has none
    // of its own. The project chat's arrive with project_instructions and
    // its skills with skills as the page loads, before anyone can type; a
    // turn the app starts sooner (the note after a file opens, Ask AI from a
    // print issue) waits in the queue until both have arrived, and the
    // handler for the later one starts it.
    if (m_availability == AgentAvailability::Ready && m_session_profile.tool_names.empty() &&
        (m_session_profile.instructions.empty() || !m_skills_received)) {
        m_queued_user_message_ids.push_back(user_message_id);
        return;
    }
    // A session with tools of its own sends its instructions when its panel
    // opens; a turn without them fails where the person can retry it.
    const bool instructions_missing = m_session_profile.instructions.empty();
    if (m_availability != AgentAvailability::Ready || instructions_missing) {
        ConversationMessage failed;
        failed.id          = document.allocate_message_id();
        failed.role        = MessageRole::Assistant;
        failed.state       = MessageState::Failed;
        failed.in_reply_to = user_message_id;
        failed.error       = instructions_missing ?
                                 AgentError{"instructions_missing", "The panel is still loading. Try again in a moment.", true} :
                                 AgentError{"agent_unavailable", "The Agent service is not available.", true};
        failed.created_at = m_persistence.timestamp();
        document.append_message(conversation_id, failed, failed.created_at);
        m_persistence.flush();
        send_envelope(Protocol::kAssistantStarted, json{{"messageId", failed.id}, {"inReplyTo", user_message_id}, {"attempt", 1}}.dump());
        send_envelope(Protocol::kAssistantFailed, json{{"messageId", failed.id}, {"error", error_json(*failed.error)}}.dump());
        return;
    }

    ConversationMessage assistant;
    assistant.id          = document.allocate_message_id();
    assistant.role        = MessageRole::Assistant;
    assistant.state       = MessageState::Streaming;
    assistant.in_reply_to = user_message_id;
    assistant.created_at = m_persistence.timestamp();
    document.append_message(conversation_id, assistant, assistant.created_at);
    m_persistence.commit();
    begin_stream(std::move(assistant), conversation_id);
}

void AgentHost::begin_stream(ConversationMessage assistant, const std::string& conversation_id)
{
    assistant.state = MessageState::Streaming;
    assistant.text.clear();
    assistant.error.reset();
    m_persistence.document().update_message(conversation_id, assistant);
    m_persistence.commit();

    ActiveStream stream;
    stream.conversation_id = conversation_id;
    stream.message         = assistant;
    m_stream               = std::move(stream);

    send_envelope(Protocol::kAssistantStarted,
                  json{{"messageId", assistant.id}, {"inReplyTo", assistant.in_reply_to}, {"attempt", assistant.attempt}}.dump());

    if (!use_chat_model(conversation_id))
        return;
    // A chat that has talked keeps the wire format its record is in: a model
    // in another format cannot read it. The chat's choice may have changed
    // under it, and a provider whose key is gone leaves it on the default.
    std::optional<ChatRecord> record  = m_persistence.document().chat_record(conversation_id);
    const ProviderProfile*    profile = m_agent_choice ? profile_for(m_agent_choice->provider) : nullptr;
    if (record && profile && record->format != (profile->account_sign_in ? m_agent_choice->format : wire_format(profile->family))) {
        fail_stream(AgentError{"chat_format_fixed",
                               "This chat's history is kept in a form that model can't read. Start a new chat to use it.", false});
        return;
    }
    AgentRequest request = make_agent_request(assistant, conversation_id, record ? std::move(*record) : ChatRecord{});
    request.on_recorded  = [this, conversation_id](const std::string& format, std::vector<RecordItem> items) {
        m_persistence.document().append_chat_record(conversation_id, format, items);
        m_persistence.commit();
    };
    // A picture or PDF goes to a blob of its own, named by the request that
    // first sends it; the document keeps only the name.
    request.keep_blob = [this, prefix = chat_record_dir(conversation_id) + "/" + request.request_id + "-",
                         count = 0](const std::string& base64) mutable -> std::optional<std::string> {
        std::string blob = prefix + std::to_string(++count);
        if (!m_persistence.write_attachment_blob(blob, base64))
            return std::nullopt;
        return blob;
    };
    if (asks_setup_check(request.skills) && purpose_recorded(conversation_id))
        mark_setup_checked(request.workspace);
    if (!m_agent || !m_agent->ready() || !m_agent->start(request))
        fail_stream(AgentError{"agent_unavailable", "The Agent service could not start this request.", true});
}

