39	interface Props {
40	  disabled: boolean;
41	  disabledReason?: string;
42	  streaming: boolean;
43	  initialText?: string;
44	  attachments: AttachmentInfo[]; // staged attachments only
45	  onSend: (text: string) => void;
46	  onStop: () => void;
47	  onAttachFiles: (files: File[], source: AttachmentSource) => void;
48	  // Opens the host's own file dialog for one kind; absent where the host
49	  // cannot, and the browser's file input is used instead.
50	  onPickFiles?: (kind: AttachmentPickKind) => void;
51	  onRemoveAttachment: (id: string) => void;
52	  onDraftChange?: (text: string) => void;
53	  draftDebounceMs?: number;
54	  // Fired on the keystroke itself, not on the debounced draft save. Anything
55	  // covering the thread uses this to get out of the way immediately.
56	  onTyping?: () => void;
57	  // What the empty field says until the person's first message, in place of
58	  // the project chat's invitation: the printer panel's likely answer to its
59	  // opening question, or the filament chat's own invitation.
60	  placeholder?: string;
61	  // The person has sent a message in this chat; from then on the field says
62	  // "Reply…", since an invitation to start reads oddly mid-conversation.
63	  started?: boolean;
64	  // The newest reply shows answer buttons; the field says typing works too.
65	  choicesOffered?: boolean;
66	  // The + menu's kinds this chat can use, where it cannot use them all: the
67	  // printer chat has no project for a 3D model to go into.
68	  attachKinds?: readonly AttachmentPickKind[];
69	  // What the field says once a file is staged, where the chat has words for
70	  // it: a photo in the printer chat waits for the person, it never sends itself.
71	  stagedPlaceholder?: string;
72	  // What the band says above the field when the field cannot be used as it
73	  // is: the notice on an earlier chat, or a recovery alert.
74	  notice?: ReactNode;
75	  // False where nothing can be attached at all, so the action is left out
76	  // rather than shown disabled: a read-only shell has only its field and Send.
77	  attachable?: boolean;
78	  // The chat's model and thinking pickers, where the host offers them.
79	  models?: ModelCatalogPayload;
80	  chatModel?: ChatModelChoice;
81	  onChooseModel?: (choice: ChatModelChoice) => void;
82	}
