84	export function Composer({
85	  disabled,
86	  disabledReason,
87	  streaming,
88	  initialText,
89	  attachments,
90	  onSend,
91	  onStop,
92	  onAttachFiles,
93	  onPickFiles,
94	  onRemoveAttachment,
95	  onDraftChange,
96	  draftDebounceMs = 300,
97	  onTyping,
98	  placeholder,
99	  started = false,
100	  choicesOffered = false,
101	  attachKinds,
102	  stagedPlaceholder,
103	  notice,
104	  attachable = true,
105	  models,
106	  chatModel,
107	  onChooseModel,
108	}: Props) {
109	  const [text, setText] = useState(initialText ?? '');
110	  const [dragging, setDragging] = useState(false);
111	  const draftTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
112	  const pendingDraft = useRef(false);
113	  const latestText = useRef(initialText ?? '');
114	  const fileInput = useRef<HTMLInputElement>(null);
115	  const field = useRef<HTMLTextAreaElement>(null);
116	  const choices = useRef<HTMLDivElement>(null);
117	  const [narrow, setNarrow] = useState(false);
118	
119	  // Grow the field to its text, up to the line limit; past it the field
120	  // scrolls. A field that is not laid out (inside a hidden view) measures 0
121	  // and keeps its height until its text next changes.
122	  useLayoutEffect(() => {
123	    const element = field.current;
124	    if (!element) return;
125	    const previous = element.style.height;
126	    element.style.height = 'auto';
127	    const content = element.scrollHeight;
128	    element.style.height = content > 0 ? `${Math.min(content, composerInputMaxHeight())}px` : previous;
129	  }, [text]);
130	
131	  // A narrow pane: when the choices at full length do not fit beside Send,
132	  // the thinking picker drops "Thinking:", and the model picker's name is
133	  // cut if it still does not fit. Measured with the labels in full (the
134	  // measuring class undoes the narrow one and the shrinking) so the answer
135	  // follows the labels' real lengths, not a fixed breakpoint.
136	  useLayoutEffect(() => {
137	    const element = choices.current;
138	    if (!element) return;
139	    const measure = () => {
140	      element.classList.add('composer-choices--measuring');
141	      const needed = element.scrollWidth;
142	      element.classList.remove('composer-choices--measuring');
143	      setNarrow(needed > element.clientWidth);
144	    };
145	    measure();
146	    const observer = new ResizeObserver(measure);
147	    observer.observe(element);
148	    return () => observer.disconnect();
149	  }, [models, chatModel]);
150	
151	  // A recovered draft arrives after the first connect; apply it only while
152	  // the composer is untouched so it never clobbers active typing.
153	  const touched = useRef(false);
154	  useEffect(() => {
155	    if (!touched.current && initialText) { setText(initialText); latestText.current = initialText; }
156	    // eslint-disable-next-line react-hooks/exhaustive-deps
157	  }, [initialText]);
158	
159	  useEffect(() => {
160	    return () => {
161	      if (draftTimer.current !== null) clearTimeout(draftTimer.current);
162	      if (pendingDraft.current) onDraftChange?.(latestText.current);
163	    };
164	  }, []);
165	
166	  const reportDraft = (value: string) => {
167	    if (!onDraftChange) return;
168	    if (draftTimer.current !== null) clearTimeout(draftTimer.current);
169	    pendingDraft.current = true;
170	    latestText.current = value;
171	    draftTimer.current = setTimeout(() => { pendingDraft.current = false; onDraftChange(value); }, draftDebounceMs);
172	  };
173	
174	  const hasSendable = attachments.some((a) => a.state === 'staged');
175	  const canSend = (!!text.trim() || hasSendable) && !disabled && !streaming;
176	
177	  const send = () => {
178	    if (!canSend) return;
179	    if (draftTimer.current !== null) clearTimeout(draftTimer.current);
180	    pendingDraft.current = false;
181	    onSend(text.trim());
182	    setText('');
183	  };
184	
185	  const handleKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
186	    if (event.key !== 'Enter' || event.shiftKey) return;
187	    // 229 is the legacy IME-processing keyCode some engines still report.
188	    if (event.nativeEvent.isComposing || event.keyCode === 229) return;
189	    event.preventDefault();
190	    send();
191	  };
192	
193	  // The host's dialog when there is one: a web view's file input shows every
194	  // file on macOS whatever `accept` says.
195	  const pickFiles = (choice: (typeof ATTACHMENT_CHOICES)[number]) => {
196	    if (onPickFiles) {
197	      onPickFiles(choice.kind);
198	      return;
199	    }
200	    if (!fileInput.current) return;
201	    fileInput.current.accept = choice.accept;
202	    fileInput.current.click();
203	  };
204	
205	  const handleFiles = (files: FileList | null, source: AttachmentSource) => {
206	    if (!files || files.length === 0) return;
207	    onAttachFiles(Array.from(files), source);
208	  };
209	
210	  const handlePickerChange = (event: ChangeEvent<HTMLInputElement>) => {
211	    handleFiles(event.target.files, 'picker');
212	    event.target.value = ''; // allow re-picking the same file
213	  };
214	
215	  const handlePaste = (event: ClipboardEvent<HTMLTextAreaElement>) => {
216	    const files = Array.from(event.clipboardData.files ?? []);
217	    if (files.length > 0) {
218	      event.preventDefault();
219	      onAttachFiles(files, 'clipboard');
220	    }
221	  };
222	
223	  const handleDrop = (event: DragEvent<HTMLDivElement>) => {
224	    event.preventDefault();
225	    setDragging(false);
226	    if (disabled) return;
227	    handleFiles(event.dataTransfer.files, 'drop');
228	  };
229	
230	  return (
231	    <div
232	      className={`composer${dragging ? ' dragging' : ''}`}
233	      onDragOver={(event) => {
234	        event.preventDefault();
235	        if (!disabled) setDragging(true);
236	      }}
237	      onDragLeave={() => setDragging(false)}
238	      onDrop={handleDrop}
239	    >
240	      {notice}
241	      <div className="composer-box">
242	        {attachments.length > 0 && (
243	          <div className="composer-attachments" aria-label="Staged attachments">
244	            {attachments.map((attachment) => (
245	              <AttachmentChip key={attachment.id} attachment={attachment} onRemove={onRemoveAttachment} />
246	            ))}
247	          </div>
248	        )}
249	        <textarea
250	          ref={field}
251	          aria-label="Message the Agent"
252	          placeholder={
253	            disabled
254	              ? disabledReason ?? 'The Agent is not available'
255	              : streaming
256	                ? 'Agent is responding…'
257	                : stagedPlaceholder && hasSendable
258	                  ? stagedPlaceholder
259	                  : !started && placeholder
260	                    ? placeholder
261	                    : choicesOffered
262	                      ? 'Or type your own answer…'
263	                      : started
264	                        ? 'Reply…'
265	                        : 'Ask about this print or request a change…'
266	          }
267	          value={text}
268	          disabled={disabled}
269	          onChange={(event) => {
270	            touched.current = true;
271	            onTyping?.();
272	            setText(event.target.value);
273	            latestText.current = event.target.value;
274	            reportDraft(event.target.value);
275	          }}
276	          onKeyDown={handleKeyDown}
277	          onPaste={handlePaste}
278	          rows={1}
279	        />
280	        <div className="composer-toolbar">
281	          <div ref={choices} className={narrow ? 'composer-choices composer-choices--narrow' : 'composer-choices'}>
282	            {/* Disabled while the Agent responds, like every choice in the
283	                toolbar; the field stays open for the next message. */}
284	            {attachable && (
285	              <ActionMenu label="Attach a file" icon="plus" above disabled={disabled || streaming}
286	                items={ATTACHMENT_CHOICES.filter((choice) => !attachKinds || attachKinds.includes(choice.kind))
287	                  .map((choice) => ({ label: choice.label, onSelect: () => pickFiles(choice) }))} />
288	            )}
289	            {models && chatModel && onChooseModel && (
290	              <ModelPickers catalog={models} choice={chatModel} disabled={disabled || streaming}
291	                onChoose={onChooseModel} />
292	            )}
293	          </div>
294	          {streaming ? (
295	            <button type="button" className="composer-send composer-stop" onClick={onStop} aria-label="Stop generating">
296	              Stop
297	            </button>
298	          ) : (
299	            <button
300	              type="button"
301	              className="composer-send"
302	              onClick={send}
303	              disabled={!canSend}
304	              aria-label="Send message"
305	            >
306	              Send
307	            </button>
308	          )}
309	        </div>
310	      </div>
311	      <input
312	        ref={fileInput}
313	        type="file"
314	        multiple
315	        className="attach-input"
316	        aria-hidden="true"
317	        tabIndex={-1}
318	        style={{ display: 'none' }}
319	        onChange={handlePickerChange}
320	      />
321	    </div>
322	  );
323	}
