// What the account's credits mean for the chat in front of the person: what
// can pay for its model, whether the next message can be paid, and the words
// for a price. The gateway keeps the ledger and still decides; this only lets
// the page say so before sending.

import { ChatModelChoice, CreditAccount, ModelCatalogPayload, ModelOptionInfo } from './bridge/protocol';

export type Tier = 'basic' | 'expert';

const plural = (count: number, one: string, many: string) => `${count} ${count === 1 ? one : many}`;

export const creditCount = (count: number) => plural(count, 'credit', 'credits');

// Free Standard messages only pay for Standard, so Expert leaves them out.
export function basicOnlyCredits(account: CreditAccount): number {
  return account.credits.lots.reduce((sum, lot) => sum + (lot.basic_only ? lot.credits : 0), 0);
}

export function spendable(account: CreditAccount, tier: string): number {
  return tier === 'expert' ? account.credits.total - basicOnlyCredits(account) : account.credits.total;
}

// Workshop's Standard messages cost nothing up to the plan's fair-use count.
function basicFreeOnPlan(account: CreditAccount): boolean {
  const { plan } = account;
  return !!plan?.unlimited_basic && (plan.basic_used_this_term ?? 0) < (plan.basic_fair_use ?? 0);
}

// A Standard message is "free this month" while something other than the
// person's own credits pays for it.
export function basicFree(account: CreditAccount | null | undefined): boolean {
  return !!account && (basicFreeOnPlan(account) || basicOnlyCredits(account) > 0);
}

export function priceWords(model: ModelOptionInfo, account: CreditAccount | null | undefined): string | undefined {
  if (model.credits === undefined) return undefined;
  if (model.tier === 'basic' && basicFree(account)) return 'free this month';
  return `${creditCount(model.credits)} a message`;
}

// The second sentence on the greyed pickers' tooltip.
export function messageCostSentence(model: ModelOptionInfo | undefined, account: CreditAccount | null | undefined): string | undefined {
  if (model?.credits === undefined) return undefined;
  if (model.tier === 'basic' && basicFree(account)) return 'Each message you send in this chat is free this month.';
  return `Each message you send in this chat costs ${creditCount(model.credits)}.`;
}

const TIER_NAMES: Record<string, string> = { basic: 'Standard', expert: 'Expert' };

export interface SendBlock {
  sentence: string;
  // Free Standard messages are left that this chat's model cannot spend.
  offerStandardChat: boolean;
}

// Why the next message of this chat cannot be paid, or nothing when it can.
export function sendBlock(account: CreditAccount | null | undefined, model: ModelOptionInfo | undefined): SendBlock | undefined {
  if (!account || !model || model.credits === undefined || !model.tier) return undefined;
  if (model.tier === 'basic' && basicFreeOnPlan(account)) return undefined;
  const available = spendable(account, model.tier);
  if (available >= model.credits) return undefined;
  const name = TIER_NAMES[model.tier] ?? model.label;
  // Under 5 there is no point in a new Standard chat: it would run out within
  // a few messages.
  if (model.tier === 'expert' && basicOnlyCredits(account) >= 5)
    return { sentence: `This ${name} chat needs ${creditCount(model.credits)} a message. Your free Standard messages can only pay for Standard.`,
      offerStandardChat: true };
  return { sentence: `You have ${creditCount(available)}; this ${name} chat needs ${model.credits} a message.`, offerStandardChat: false };
}

// "About 5 Expert messages left", once the balance is under one session's
// worth of the chat's model. A session of about five messages is the design's
// placeholder (from four harness sessions, not from engaged use).
const LOW_MESSAGES = 5;

export function lowNotice(account: CreditAccount | null | undefined, model: ModelOptionInfo | undefined): string | undefined {
  if (!account || !model || model.credits === undefined || !model.tier) return undefined;
  if (model.tier === 'basic' && basicFree(account)) return undefined;
  const messages = Math.floor(spendable(account, model.tier) / model.credits);
  if (messages < 1 || messages > LOW_MESSAGES) return undefined;
  return `About ${plural(messages, `${TIER_NAMES[model.tier] ?? model.label} message`, `${TIER_NAMES[model.tier] ?? model.label} messages`)} left`;
}

export function aliasOfTier(catalog: ModelCatalogPayload | undefined, tier: Tier): ChatModelChoice | undefined {
  for (const provider of catalog?.providers ?? [])
    for (const model of provider.models)
      if (model.tier === tier)
        return { provider: provider.id, model: model.id, effort: model.defaultEffort ?? '' };
  return undefined;
}

export function tierPrice(catalog: ModelCatalogPayload | undefined, tier: Tier): number | undefined {
  for (const provider of catalog?.providers ?? [])
    for (const model of provider.models)
      if (model.tier === tier && model.credits !== undefined)
        return model.credits;
  return undefined;
}

// The composer's credits ring and the panel it opens (board 2a on the "JusPrin
// v2" canvas): a small ring of what is left, no number and no animation;
// hovering or tapping opens the total, translated into messages, then a bar per
// kind of credit that expires, soonest first. Credits that never expire have no
// limit to measure against, so they are a plain number.
//
// What the ring measures against is open (plan decision 13): the sum of what
// each lot started with, the board's placeholder.

import { useEffect, useRef, useState } from 'react';
import { CreditAccount, CreditLot } from '../bridge/protocol';
import { basicOnlyCredits, creditCount, spendable } from '../credits';

const RING = 16;
const STROKE = 3;

function shortDate(iso: string): string {
  return new Date(iso).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
}

function lotName(lot: CreditLot, account: CreditAccount): string {
  switch (lot.kind) {
    case 'signup': return 'First-month credits';
    case 'trickle': return 'Free Standard messages';
    case 'subscription': return `${account.plan?.name ?? 'Plan'} credits`;
    case 'pack': return 'Bought credits';
    // What to call a reward is open (plan decision 13).
    case 'reward': return 'Report credits';
    default: return 'Credits';
  }
}

interface Row { key: string; name: string; left: number; of?: number; date: string }

function rows(account: CreditAccount): Row[] {
  const expiring: (Row & { at: string })[] = [];
  let never = new Map<string, number>();
  for (const lot of account.credits.lots) {
    if (lot.expires_at) {
      expiring.push({ key: `${lot.kind}-${lot.expires_at}`, name: lotName(lot, account), left: lot.credits, of: lot.granted, at: lot.expires_at,
        date: `${lot.kind === 'trickle' ? 'Resets' : 'Expires'} ${shortDate(lot.expires_at)}` });
    } else if (lot.credits > 0) {
      const name = lotName(lot, account);
      never = never.set(name, (never.get(name) ?? 0) + lot.credits);
    }
  }
  const { plan } = account;
  if (plan?.unlimited_basic && plan.basic_fair_use && plan.renews_at) {
    const left = Math.max(plan.basic_fair_use - (plan.basic_used_this_term ?? 0), 0);
    expiring.push({ key: 'fair-use', name: 'Free Standard messages', left, of: plan.basic_fair_use, at: plan.renews_at,
      date: `Resets ${shortDate(plan.renews_at)}. After ${plan.basic_fair_use}, Standard is 1 credit a message until then.` });
  }
  expiring.sort((a, b) => a.at.localeCompare(b.at));
  return [...expiring, ...[...never].map(([name, left]) => ({ key: name, name, left, date: 'Never expire' }))];
}

// The ring's share: what is left of what the lots started with.
export function ringShare(account: CreditAccount): number {
  const started = account.credits.lots.reduce((sum, lot) => sum + lot.granted, 0);
  return started > 0 ? Math.min(account.credits.total / started, 1) : 0;
}

function Ring({ share, low }: { share: number; low: boolean }) {
  const radius = (RING - STROKE) / 2;
  const circumference = 2 * Math.PI * radius;
  return <svg className={low ? 'credit-ring credit-ring--low' : 'credit-ring'} viewBox={`0 0 ${RING} ${RING}`} aria-hidden="true">
    <circle className="credit-ring-track" cx={RING / 2} cy={RING / 2} r={radius} fill="none" strokeWidth={STROKE} />
    <circle className="credit-ring-fill" cx={RING / 2} cy={RING / 2} r={radius} fill="none" strokeWidth={STROKE}
      strokeDasharray={`${share * circumference} ${circumference}`} transform={`rotate(-90 ${RING / 2} ${RING / 2})`} />
  </svg>;
}

export function BalancePanel({ account, expertPrice, low, onGetMore, onSeeUsage }: {
  account: CreditAccount;
  expertPrice: number;
  low: boolean;
  onGetMore: () => void;
  onSeeUsage: () => void;
}) {
  const [open, setOpen] = useState(false);
  const closing = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => () => { if (closing.current !== null) clearTimeout(closing.current); }, []);
  const keepOpen = () => {
    if (closing.current !== null) clearTimeout(closing.current);
    closing.current = null;
    setOpen(true);
  };
  // The pointer crosses a gap on its way from the ring to the panel's actions.
  const closeSoon = () => { closing.current = setTimeout(() => setOpen(false), 200); };

  const total = account.credits.total;
  const expert = Math.floor(spendable(account, 'expert') / expertPrice);
  const standardUnit = expert === 1 ? 'message' : 'messages';
  return <div className="credit-balance" onMouseEnter={keepOpen} onMouseLeave={closeSoon}
    onKeyDown={(event) => { if (event.key === 'Escape') setOpen(false); }}>
    <button type="button" className="credit-ring-button" aria-label="Credits left" aria-expanded={open}
      onClick={() => setOpen((shown) => !shown)}>
      <Ring share={ringShare(account)} low={low} />
    </button>
    {open && <div className="credit-panel" role="dialog" aria-label="Credits">
      <div className="credit-panel-total">
        <strong>{creditCount(total).replace(/ .*/, '')} {total === 1 ? 'credit' : 'credits'} left</strong>
        <span>That is {total} Standard or {expert} Expert {standardUnit}.</span>
      </div>
      <div className="credit-panel-lots">
        {rows(account).map((row) => <div key={row.key} className="credit-lot">
          <div className="credit-lot-line">
            <strong>{row.name}</strong>
            <span>{row.of === undefined ? `${row.left} left` : `${row.left} of ${row.of} left`}</span>
          </div>
          {row.of !== undefined && <div className="credit-lot-bar">
            <div className="credit-lot-fill" style={{ width: `${row.of > 0 ? Math.min(row.left / row.of, 1) * 100 : 0}%` }} />
          </div>}
          <span className="credit-lot-date">{row.date}</span>
        </div>)}
        <p className="credit-panel-rule">Expiring credits are used first.</p>
      </div>
      <div className="credit-panel-actions">
        <button type="button" className="link" onClick={onGetMore}>Get more credits</button>
        <button type="button" className="link" onClick={onSeeUsage}>See usage</button>
      </div>
    </div>}
  </div>;
}

// A person with only free Standard messages has no balance on the toolbar
// (boards 3d and 6a); the message box says what is there instead.
export function showsRing(account: CreditAccount): boolean {
  return account.credits.total > basicOnlyCredits(account);
}

