describe('the check before sending', () => {
  it('leaves Send alone when the message can be paid', () => {
    renderComposer({ text: 'Hello', account: balance(lot('signup', 5)) });
    expect(send()).toBeEnabled();
    expect(screen.queryByRole('button', { name: 'Get more credits' })).toBeNull();
  });

  it('disables Send, says why, offers one action and keeps the words', () => {
    const composerCredits = credits(balance(lot('pack', 3)));
    renderComposer({ text: 'The tip curled up', composerCredits });
    expect(send()).toBeDisabled();
    expect(screen.getByText('You have 3 credits; this Expert chat needs 5 a message.')).toBeTruthy();
    expect(screen.getByRole('button', { name: 'Get more credits' })).toBeTruthy();
    expect(screen.queryByRole('button', { name: 'New Standard chat' })).toBeNull();
    expect(screen.getByRole('textbox')).toHaveValue('The tip curled up');
  });

  it('adds New Standard chat only when free Standard messages are what is left', async () => {
    const composerCredits = credits(balance(lot('trickle', 50, true)));
    renderComposer({ text: 'The tip curled up', composerCredits });
    expect(send()).toBeDisabled();
    expect(screen.getByText('This Expert chat needs 5 credits a message. Your free Standard messages can only pay for Standard.')).toBeTruthy();
    await userEvent.click(screen.getByRole('button', { name: 'New Standard chat' }));
    expect(composerCredits.onNewChat).toHaveBeenCalledWith(onStandard, 'The tip curled up');
  });

  it('offers no New Standard chat under 5 credits', () => {
    expect(sendBlock(balance(lot('trickle', 4, true)), expert)).toEqual({
      sentence: 'You have 0 credits; this Expert chat needs 5 a message.', offerStandardChat: false });
  });

  it('lets free Standard messages pay for a Standard chat', () => {
    expect(sendBlock(balance(lot('trickle', 4, true)), standard)).toBeUndefined();
  });

  it('never blocks a model on the person’s own key', () => {
    expect(sendBlock(balance(), own)).toBeUndefined();
  });

  it('says once that few messages are left, in the warning colour', async () => {
    const seen = new Set<string>();
    const composerCredits = credits(balance(lot('pack', 25)), {
      lowNoticeSeen: (notice) => seen.has(notice),
      onLowNoticeSeen: (notice) => { seen.add(notice); },
    });
    const onSend = vi.fn();
    renderComposer({ text: 'Hello', composerCredits, onSend });
    expect(screen.getByText('About 5 Expert messages left')).toBeTruthy();
    expect(document.querySelector('.credit-ring--low')).toBeTruthy();
    await userEvent.click(send());
    expect(onSend).toHaveBeenCalledWith('Hello');
    expect(seen.has('About 5 Expert messages left')).toBe(true);
  });
});

