1904	        send_bridge_error("busy", "Another reply is currently streaming.", envelope_id);
1905	        return;
1906	    }
1907	    ConversationMessage retried = *message;
1908	    ++retried.attempt;
1909	    begin_stream(std::move(retried), conversation_id);
