    m_rejected_calls   = 0;
    m_paused_turns     = 0;
    m_kind = request.purpose == AgentRequest::Purpose::ConversationTitle ? RequestKind::ConversationTitle : RequestKind::Reply;
    begin_transcript(request);
    return post();
}
