"""Print reports and the credits they earn: granted at once when the automatic
checks pass, taken back once if a review finds the report invalid."""
from datetime import timedelta
from typing import Dict, List

from django.conf import settings
from django.db import IntegrityError, transaction
from django.utils import timezone

from .ledger import live_lots
from .models import CreditGrant, PrintReport, PrintReportReview


class ReportRefused(Exception):
    def __init__(self, code: str):
        super().__init__(code)
        self.code = code


def _reward_ref(report: PrintReport) -> str:
    return f'report:{report.id}'


def _invalid_ref(report: PrintReport) -> str:
    return f'report-invalid:{report.id}'


def _earns(user_id: int, now) -> bool:
    invalid = PrintReportReview.objects.filter(report__user_id=user_id, invalid=True).count()
    if invalid >= settings.JUSPRIN_V2_REPORT_INVALID_LIMIT:
        return False
    rewarded_today = CreditGrant.objects.filter(user_id=user_id, kind=CreditGrant.REWARD,
                                                created_at__gte=now - timedelta(days=1)).count()
    return rewarded_today < settings.JUSPRIN_V2_REPORT_DAILY_REWARDS


def submit_report(user, gcode_hash: str, outcome: str, text: str, facts: Dict, photos: List[str]) -> PrintReport:
    """Stores the report, and grants its reward unless the person has stopped
    earning. The caller has checked the text and the photos."""
    now = timezone.now()
    try:
        with transaction.atomic():
            report = PrintReport.objects.create(user=user, gcode_hash=gcode_hash, outcome=outcome, text=text,
                                                facts=facts, photos=photos, rewarded=_earns(user.id, now))
            if report.rewarded:
                credits = settings.JUSPRIN_V2_REPORT_CREDITS
                CreditGrant.objects.create(user=user, kind=CreditGrant.REWARD, credits_granted=credits,
                                           credits_remaining=credits, source_ref=_reward_ref(report))
    except IntegrityError:
        raise ReportRefused('already_reported')
    return report


def is_reported(user, gcode_hash: str) -> bool:
    return PrintReport.objects.filter(user=user, gcode_hash=gcode_hash).exists()


def review_report(report: PrintReport, invalid: bool, note: str = '') -> PrintReportReview:
    """Records the review. An invalid report that earned loses it once, from what
    is left: the balance can reach zero, not below, and the rest is forgiven."""
    with transaction.atomic():
        review, _ = PrintReportReview.objects.update_or_create(report=report, defaults={'invalid': invalid, 'note': note})
        if invalid and report.rewarded:
            _take_back(report)
    return review


def _take_back(report: PrintReport) -> None:
    credits = settings.JUSPRIN_V2_REPORT_CREDITS
    now = timezone.now()
    # Locks the person's lots in the order charge_turn takes them.
    lots = list(live_lots(report.user_id, now).select_for_update())
    _, created = CreditGrant.objects.get_or_create(
        user_id=report.user_id, source_ref=_invalid_ref(report),
        defaults={'kind': CreditGrant.ADJUSTMENT, 'credits_granted': -credits, 'credits_remaining': 0})
    if not created:
        return
    # The reward's own lot first, then what else the person holds. Free Standard
    # messages are left alone: they never came from the reward.
    own = [lot for lot in lots if lot.source_ref == _reward_ref(report)]
    others = [lot for lot in lots if lot.source_ref != _reward_ref(report) and not lot.basic_only]
    owed = credits
    for lot in own + others:
        taken = min(owed, lot.credits_remaining)
        if taken > 0:
            lot.credits_remaining -= taken
            lot.save(update_fields=['credits_remaining'])
            owed -= taken


def report_activity(user, since) -> List[Dict]:
    """The Account usage table's rows for reports: what each earned, and what a
    review took back with its reason."""
    rows = []
    reports = PrintReport.objects.filter(user=user).select_related('printreportreview')
    by_ref = {_reward_ref(report): report for report in reports}
    by_ref.update({_invalid_ref(report): report for report in reports})
    grants = CreditGrant.objects.filter(user=user, created_at__gte=since, source_ref__in=by_ref.keys())
    for grant in grants:
        report = by_ref[grant.source_ref]
        title = 'Print report · ' + report.facts.get('project', report.gcode_hash[:8])
        row = {'date': grant.created_at.date().isoformat(), 'title': title, 'credits': grant.credits_granted}
        if grant.kind == CreditGrant.REWARD:
            rows.append({**row, 'kind': 'report'})
        else:
            rows.append({**row, 'kind': 'report_removed', 'note': report.printreportreview.note})
    return rows
