15	const LivePrint* live_print(const GcodePrint& print, const std::vector<LivePrint>& live)
16	{
17	    if (!print.finished_at.empty())
18	        return nullptr;
19	    const auto found = std::find_if(live.begin(), live.end(), [&print](const LivePrint& job) {
20	        return job.printer_id == print.printer_id && job.job_key == print.job_id;
21	    });
22	    return found == live.end() ? nullptr : &*found;
23	}
