27	void count_print(HistorySummary& summary, const GcodePrint& print, const std::vector<LivePrint>& live)
28	{
29	    ++summary.prints;
30	    if (live_print(print, live) != nullptr)
31	        ++summary.printing_now;
32	    // The records write UTC with a trailing Z in one format, so their times
33	    // order as text.
34	    if (print.finished_at > summary.last_finished_at)
35	        summary.last_finished_at = print.finished_at;
36	}
37	
38	void count_destinations(HistorySummary& summary, const GcodeRecord& record)
39	{
40	    for (const GcodeDestination& destination : record.destinations)
41	        ++(destination.kind == GcodeDestination::Kind::Export ? summary.exports : summary.sends);
42	}
43	
44	// Every printer card the record belongs to: the one its printer preset stands
45	// for, and each one it was sent to or printed on.
46	std::set<std::string> cards_of(const GcodeRecord& record, const HistoryFacts& facts)
47	{
48	    std::set<std::string> cards;
49	    const auto add = [&cards](std::string card) {
50	        if (!card.empty())
51	            cards.insert(std::move(card));
52	    };
53	    add(facts.card_for_preset(record.printer));
54	    for (const GcodeDestination& destination : record.destinations)
55	        if (destination.kind == GcodeDestination::Kind::Send)
56	            add(facts.card_for_printer(destination.printer_id, destination.printer_name));
57	    for (const GcodePrint& print : record.prints)
58	        add(facts.card_for_printer(print.printer_id, print.printer_name));
59	    return cards;
60	}
61	
62	void set_if_present(json& target, const char* key, const std::string& value)
63	{
64	    if (!value.empty())
65	        target[key] = value;
66	}
67	
68	json destination_json(const GcodeDestination& destination, const HistoryFacts& facts)
69	{
70	    json out{{"id", destination.id}, {"at", destination.at}};
71	    if (destination.kind == GcodeDestination::Kind::Export) {
72	        out["kind"]  = "export";
73	        out["path"]  = destination.path;
74	        out["check"] = facts.check_export(destination);
75	        return out;
76	    }
77	    out["kind"]           = "send";
78	    out["printerName"]    = destination.printer_name;
79	    out["delivered"]      = !destination.delivered_at.empty();
80	    out["startRequested"] = destination.start_requested;
81	    set_if_present(out, "printerId", facts.card_for_printer(destination.printer_id, destination.printer_name));
82	    return out;
83	}
84	
85	json print_json(const GcodePrint& print, const HistoryFacts& facts, const std::vector<LivePrint>& live)
86	{
87	    json out{{"id", print.id}, {"printerName", print.printer_name}, {"startedAt", print.started_at}};
88	    set_if_present(out, "printerId", facts.card_for_printer(print.printer_id, print.printer_name));
89	    set_if_present(out, "finishedAt", print.finished_at);
90	    if (const LivePrint* job = live_print(print, live)) {
91	        json now = json::object();
92	        if (job->percent >= 0)
93	            now["percent"] = job->percent;
94	        if (job->remaining_seconds > 0)
95	            now["remainingSeconds"] = job->remaining_seconds;
96	        out["live"] = std::move(now);
97	    }
98	    return out;
99	}
100	
101	json entry_json(const HistoryProject& project, const GcodeRecord& record, const HistoryFacts& facts,
102	                const std::vector<LivePrint>& live)
103	{
104	    json out{{"projectId", project.id},
105	             {"projectName", project.name},
106	             {"hash", record.hash},
107	             {"name", Agent::gcode_display_name(record)},
108	             {"plateName", record.plate_name},
109	             {"createdAt", record.created_at},
110	             {"kept", facts.kept(project.id, record.hash)},
111	             {"printAgain", facts.print_again(project.id, record)}};
112	    const Agent::SliceStatistics& statistics = record.statistics;
113	    if (statistics.print_time_seconds > 0.0)
114	        out["printTimeSeconds"] = statistics.print_time_seconds;
115	    if (statistics.material_grams > 0.0)
116	        out["grams"] = statistics.material_grams;
117	    if (statistics.layer_count > 0)
118	        out["layers"] = statistics.layer_count;
119	    set_if_present(out, "printer", facts.printer_label(record.printer));
120	    set_if_present(out, "material", facts.material_label(record.material));
121	    set_if_present(out, "process", facts.process_label(record.process));
122	
123	    // Open in chat goes to the marker of where the G-code first went out.
124	    const auto first = std::min_element(record.destinations.begin(), record.destinations.end(),
125	                                        [](const GcodeDestination& a, const GcodeDestination& b) { return a.seq < b.seq; });
126	    if (first != record.destinations.end() && !first->conversation_id.empty()) {
127	        out["conversationId"] = first->conversation_id;
128	        out["markerId"]       = first->id;
129	    }
130	
131	    json cards = json::array();
132	    for (const std::string& card : cards_of(record, facts))
133	        cards.push_back(card);
134	    out["printerIds"] = std::move(cards);
135	
136	    json destinations = json::array();
137	    for (const GcodeDestination& destination : record.destinations)
138	        destinations.push_back(destination_json(destination, facts));
139	    out["destinations"] = std::move(destinations);
140	    json prints = json::array();
141	    for (const GcodePrint& print : record.prints)
142	        prints.push_back(print_json(print, facts, live));
143	    out["prints"] = std::move(prints);
144	    return out;
145	}
