148	
149	HistorySummary summarize(const std::vector<GcodeRecord>& records, const std::vector<LivePrint>& live)
150	{
151	    HistorySummary summary;
152	    summary.gcodes = records.size();
153	    for (const GcodeRecord& record : records) {
154	        count_destinations(summary, record);
155	        for (const GcodePrint& print : record.prints)
156	            count_print(summary, print, live);
157	    }
158	    return summary;
159	}
160	
161	HistorySummary summarize_printer(const std::vector<HistoryProject>& projects, const std::string& card_id,
162	                                 const HistoryFacts& facts, const std::vector<LivePrint>& live)
163	{
164	    HistorySummary summary;
165	    for (const HistoryProject& project : projects)
166	        for (const GcodeRecord& record : project.records) {
167	            if (cards_of(record, facts).count(card_id) == 0)
168	                continue;
169	            ++summary.gcodes;
170	            for (const GcodeDestination& destination : record.destinations)
171	                if (destination.kind == GcodeDestination::Kind::Send &&
172	                    facts.card_for_printer(destination.printer_id, destination.printer_name) == card_id)
173	                    ++summary.sends;
174	            for (const GcodePrint& print : record.prints)
175	                if (facts.card_for_printer(print.printer_id, print.printer_name) == card_id)
176	                    count_print(summary, print, live);
177	        }
178	    return summary;
179	}
180	
181	json history_entries(const std::vector<HistoryProject>& projects, const HistoryFacts& facts, const std::vector<LivePrint>& live)
182	{
183	    std::vector<std::pair<const HistoryProject*, const GcodeRecord*>> all;
184	    for (const HistoryProject& project : projects)
185	        for (const GcodeRecord& record : project.records)
186	            all.emplace_back(&project, &record);
187	    std::stable_sort(all.begin(), all.end(), [](const auto& a, const auto& b) { return a.second->created_at > b.second->created_at; });
188	    json entries = json::array();
189	    for (const auto& [project, record] : all)
190	        entries.push_back(entry_json(*project, *record, facts, live));
191	    return entries;
192	}
