GcodeRecord gcode(const std::string& hash, const std::string& created_at, const std::string& printer = "Bambu X1C preset")
{
    GcodeRecord record;
    record.hash       = hash;
    record.created_at = created_at;
    record.plate_name = "Plate 1";
