    return record;
}

GcodeDestination& add_export(GcodeRecord& record, const std::string& path)
{
    GcodeDestination exported;
    exported.id   = "d-" + std::to_string(record.destinations.size() + 1);
    exported.seq  = record.destinations.size() + 1;
