#!/usr/bin/env python3
# Serves copies of the built Agent and Home pages with a script injected that
# logs bridge traffic and runs commands queued here. Test output only.
import json, sys, threading, time, os, uuid
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse, parse_qs

ROOT = os.path.dirname(os.path.abspath(__file__))
PORT = int(sys.argv[1]) if len(sys.argv) > 1 else 8791
LOG = open(os.path.join(ROOT, 'traffic.log'), 'a', buffering=1)
queues, results, seen = {}, {}, {}
lock = threading.Lock()


class H(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def reply(self, code, body=b'', ctype='application/json'):
        self.send_response(code)
        self.send_header('Content-Type', ctype)
        self.send_header('Cache-Control', 'no-store')
        self.send_header('Content-Length', str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        url = urlparse(self.path)
        q = parse_qs(url.query)
        if url.path == '/cmd':
            page = q.get('page', [''])[0]
            with lock:
                seen[page] = time.time()
                item = queues.get(page, [])
                cmd = item.pop(0) if item else None
            return self.reply(200, json.dumps(cmd).encode()) if cmd else self.reply(204)
        if url.path == '/pages':
            with lock:
                now = time.time()
                return self.reply(200, json.dumps({k: round(now - v, 1) for k, v in seen.items()}).encode())
        if url.path == '/result':
            with lock:
                out = results.pop(q['id'][0], None)
            return self.reply(200, json.dumps({'out': out}).encode()) if out is not None else self.reply(204)
        path = os.path.join(ROOT, url.path.lstrip('/'))
        if os.path.isfile(path):
            return self.reply(200, open(path, 'rb').read(), 'text/html; charset=utf-8')
        return self.reply(404)

    def do_POST(self):
        body = self.rfile.read(int(self.headers.get('Content-Length', 0)))
        url = urlparse(self.path)
        if url.path == '/log':
            LOG.write(time.strftime('%H:%M:%S ') + body.decode(errors='replace') + '\n')
        elif url.path == '/result':
            data = json.loads(body)
            with lock:
                results[data['id']] = data['out']
        elif url.path == '/enqueue':
            data = json.loads(body)
            cid = uuid.uuid4().hex
            with lock:
                queues.setdefault(data['page'], []).append({'id': cid, 'js': data['js']})
            return self.reply(200, json.dumps({'id': cid}).encode())
        elif url.path == '/save':
            name = parse_qs(url.query)['name'][0]
            open(os.path.join(ROOT, 'snaps', name), 'wb').write(body)
        self.reply(200)


ThreadingHTTPServer(('127.0.0.1', PORT), H).serve_forever()

(function () {
  var page = (window.__PROBE_PAGE || 'page') + (location.search ? location.search.replace('?panel=', '-') : '');
  function post(path, body) { return fetch(path, { method: 'POST', body: JSON.stringify(body) }).catch(function () {}); }
  function brief(env) {
    var text = JSON.stringify(env);
    return text.length > 1500 ? text.slice(0, 1500) + '…' : text;
  }
  (function wait() {
    var bridge = window.__jusprinBridge;
    if (!bridge) return setTimeout(wait, 30);
    var deliver = bridge.deliver;
    bridge.deliver = function (env) {
      post('/log', { page: page, in: env && env.type, env: brief(env) });
      return deliver.apply(this, arguments);
    };
    post('/log', { page: page, ready: true });
    if (window.wx && window.wx.postMessage) {
      var postMessage = window.wx.postMessage.bind(window.wx);
      window.wx.postMessage = function (text) {
        try { var m = JSON.parse(text); post('/log', { page: page, out: m.type, env: brief(m) }); } catch (e) {}
        return postMessage(text);
      };
    }
  })();
  window.__text = function (selector) {
    var el = selector ? document.querySelector(selector) : document.body;
    return el ? el.innerText : null;
  };
  window.__press = function (label) {
    var all = Array.prototype.slice.call(document.querySelectorAll('button,a,[role=menuitem]'));
    var hit = all.filter(function (b) { return (b.getAttribute('aria-label') || b.innerText || '').trim() === label; })[0];
    if (!hit) return 'no button ' + label + ' among: ' + all.map(function (b) { return (b.getAttribute('aria-label') || b.innerText || '').trim(); }).join(' | ');
    if (hit.disabled) return 'disabled ' + label;
    hit.click();
    return 'pressed ' + label;
  };
  window.__snap = function (name) {
    var a = document.activeElement;
    if (a) a.setAttribute('data-visual-focus', '');
    var size = document.documentElement.clientWidth + 'x' + document.documentElement.clientHeight;
    return fetch('/save?name=' + encodeURIComponent(page + '-' + name + '-' + size + '.html'), { method: 'POST', body: document.documentElement.outerHTML }).then(function () { return size; });
  };
