class FakeStorage:
    """lib.file_storage, in memory."""

    def __init__(self):
        self.files = {}
        self.on_save = None

    def save_file_obj(self, path, file_obj, container, syndicate_name, long_term_storage=True):
        if self.on_save is not None:
            self.on_save()
        self.files[(container, path)] = file_obj.getvalue()

    def retrieve_to_file_obj(self, path, file_obj, container, long_term_storage=True):
        if (container, path) in self.files:
            file_obj.write(self.files[(container, path)])

    def delete_dir(self, dir_path, container, long_term_storage=True):
        prefix = dir_path.rstrip('/') + '/'
        for key in [k for k in self.files if k[0] == container and k[1].startswith(prefix)]:
            del self.files[key]

    def paths(self):
        return sorted(path for container, path in self.files if container == CONTAINER)

    def record(self, path):
        return json.loads(gzip.decompress(self.files[(CONTAINER, path)]))


